import fs from "fs";
import { z } from "zod";
import { IMAGE_META_JSON } from "@/config/paths";
import { tryDecodeUrlComponent } from "@/utils/links/url";

const imageMetaSchema = z.object({
  width: z.number(),
  height: z.number(),
  blurDataURL: z.string().optional(),
});

const imageManifestSchema = z.record(z.string(), imageMetaSchema);

export type ImageMeta = z.infer<typeof imageMetaSchema>;

// filename → meta, generated by scripts/generateImageMeta.ts from the R2
// bucket. Loaded once per server process; drafts and unknown images miss.
let manifest: Record<string, ImageMeta> | null = null;

function loadManifest(): Record<string, ImageMeta> {
  if (!fs.existsSync(IMAGE_META_JSON)) return {};
  const raw: unknown = JSON.parse(fs.readFileSync(IMAGE_META_JSON, "utf8"));
  const parsed = imageManifestSchema.parse(raw);
  if (raw && typeof raw === "object" && Object.hasOwn(raw, "__proto__")) {
    Object.defineProperty(parsed, "__proto__", {
      value: imageMetaSchema.parse(
        (raw as Record<string, unknown>)["__proto__"]
      ),
      enumerable: true,
      configurable: true,
      writable: true,
    });
  }
  return parsed;
}

export function getImageMeta(src: string): ImageMeta | null {
  const match = src.match(/^\/images\/([^/]+)$/);
  if (!match) return null;
  const filename = tryDecodeUrlComponent(match[1]);
  if (filename === null) return null;
  const metadata = (manifest ??= loadManifest());
  return Object.hasOwn(metadata, filename) ? metadata[filename] : null;
}
